let selectedTier=1;
function selectTier(t){selectedTier=t;document.querySelectorAll('#tier-chips .chip').forEach(c=>c.classList.toggle('active',+c.dataset.tier===t));document.getElementById('combat-picker-sub').textContent='Tier '+t;renderMonsterList();}
function renderMonsterList(){
  const el=document.getElementById('monster-list');if(!el)return;
  const list=Object.entries(MONSTERS).filter(([,m])=>m.tier===selectedTier);
  el.innerHTML=list.map(([id,m])=>{
    const cl=getCombatLevel();const req=(m.tier-1)*15;const unlocked=cl>=req;const fighting=G.activeMonster===id;
    /* b217: the second line used to be one dot-separated dev string —
       "Vermin · Weak: sword · HP 8 · ATK 2" — which reads as a debug printout
       and buries the two numbers a player actually compares between foes.
       Flavour stays on the left as a sentence; HP and ATK move right into a
       fixed tabular column so rows line up and can be scanned down. */
    const lockGly = (window.HR && window.HR.icon) ? (window.HR.icon('uiLock', 11, 'currentColor') || '') : '';
    const rightSide = !unlocked
      ? `<span class="mr-lock">${lockGly}CL ${req}</span>`
      : fighting
        ? '<span class="mr-fighting">Fighting</span>'
        : `<span class="mr-stats"><i>${m.hp}<em>HP</em></i><i>${m.atk}<em>ATK</em></i></span>`;
    return `<button class="monster-row ${fighting?'fighting':''}" ${unlocked?'':'disabled'} onclick="${unlocked?`startCombat('${id}')`:''}">
      <span class="mi">${m.icon}</span>
      <div style="flex:1;min-width:0">
        <span class="mn">${m.name}${m.boss?' <span class="tag">Boss</span>':''}</span>
        <span class="ms">${m.family||'Monster'} · weak to ${WEAPON_TYPES[m.weaponWeak]||'—'}</span>
      </div>
      ${rightSide}
    </button>`;
  }).join('');
}
function renderCombat(){
  const el=document.getElementById('combat-area');if(!el)return;
  /* Tester report (paione): the auto-eat food dropdown "keeps closing every few
     ticks". renderCombat rebuilds this area's innerHTML on every combat tick,
     which destroys the <select> mid-pick and closes its native menu. If the
     player is actively choosing food (the select holds focus while its menu is
     open), skip the repaint for this tick — the fight keeps running underneath;
     only the HP numbers pause for the moment the menu is open. */
  const _ae=document.activeElement;
  if(_ae && _ae.tagName==='SELECT' && el.contains(_ae)) return;
  const stop=document.getElementById('combat-stop');
  if(!G.activeMonster){
    el.innerHTML=`${renderBountyPanel()}<div class="arena"><div class="fighter"><div class="portrait">🧍</div><div class="fname">You</div><div class="fhp">${G.playerHp}/${G.playerMaxHp}</div></div><div class="vs">⚔️</div><div class="fighter enemy"><div class="portrait">❓</div><div class="fname">Choose a foe</div><div class="fhp">—</div></div></div><div class="empty"><span class="em-icon">⚔️</span>Pick a monster from the list to begin.</div>`;
    stop.style.display='none';return;
  }
  const m=MONSTERS[G.activeMonster];
  const php=(G.playerHp/G.playerMaxHp)*100,mhp=(G.monsterHp/G.monsterMaxHp)*100;
  /* b220: the auto-eat picker offers only what auto-eat may actually eat —
     Provisions (foodClass 'healing'). Listing Feasts & Draughts here let a
     player select a Void Banquet as their auto-eat food and then watch it
     never fire; the engine filter is in HearthriseAuto.maybeAutoEat(). */
  const _autoEatOk=(id)=>window.HearthriseAuto&&typeof window.HearthriseAuto.isAutoEatable==='function'
    ? window.HearthriseAuto.isAutoEatable(ITEMS[id])
    : !!(ITEMS[id]&&ITEMS[id].heals&&ITEMS[id].foodClass!=='buff');
  const foods=Object.entries(G.inventory).filter(([id])=>_autoEatOk(id));
  /* ── b224: the food row, rebuilt ────────────────────────────────────────
     It used to be one unlabelled `Auto-eat:` dropdown. Three things were
     wrong with that on the screen where you actually take damage:
       • there was no way to heal by hand — and for a new player there is no
         other kind of healing, because Auto-Eat is a 5,000g Store trait they
         do not own yet. The dropdown was the only food control in combat and
         it configured a feature they could not use.
       • it never said what auto-eat does, when it fires, or that it only ever
         spends Provisions.
       • with an empty bag it rendered as a lone "None" option, which reads as
         a broken control rather than "you have no healing food".
     Now: a real Eat button first, then auto-eat, then one line of plain
     English about whichever of those two is actually in play.

     ── b227 (Tyler): "the eat food button is hard to read, and it needs to be
     closer to the character screen. Right now I have to scroll down to see it."
     He was right, and the reason is structural: this element renders into
     #combat-area, which sits UNDER the arena stage and is the only scrolling
     box on the screen. On a 900×760 window #combat-area was 91px tall holding
     796px of content, so the one control that saves your life was 470px below
     the fold DURING a fight.

     The Eat BUTTON therefore no longer renders here. It is painted onto the
     player's side of the arena stage — beside their own portrait and HP bar,
     inside the non-scrolling region — by HearthriseCombatHud in
     src/features/combat-render.js. What stays here is the auto-eat CONFIG,
     which is a setting rather than an action and does not need to be reachable
     inside one second.

     Also gone from this box, and for the same reason: the six-tile `.calc`
     grid, the drop-rate line, and (in injectCombatExtras) the Forecast card.
     They are reference tables you consult between decisions, not things you
     watch — so they became the two modals hung off the ENEMY portrait. */
  const _hasAutoEat = (typeof hasTrait === 'function') && hasTrait('auto_eat');
  const _eatCfg = (window.HearthriseAuto && window.HearthriseAuto.getEat) ? window.HearthriseAuto.getEat() : null;
  const _threshPct = Math.round(((_eatCfg && _eatCfg.threshold) || 0.5) * 100);
  const _foodNote = !foods.length
    ? 'No Provisions in your bag. Cook fish or bake bread — Feasts &amp; Draughts heal too, but only when you use them by hand.'
    : _hasAutoEat
      ? `Auto-eat spends one Provision when your HP falls below ${_threshPct}%. Feasts &amp; Draughts are never auto-eaten.`
      : `Auto-eat is a Store unlock — until then, healing in combat is manual: press Eat beside your champion.`;
  el.innerHTML=`
    ${renderBountyPanel()}
    <div class="arena">
      <div class="fighter"><div class="portrait">🧍</div><div class="fname">You</div><div class="fhp">${G.playerHp}/${G.playerMaxHp}</div><div class="bar hp"><i style="width:${php}%"></i></div></div>
      <div class="vs">⚔️</div>
      <div class="fighter enemy"><div class="portrait">${m.icon}</div><div class="fname">${m.name}${m.boss?' <span class="tag">BOSS</span>':''}</div><div class="fhp">${G.monsterHp}/${G.monsterMaxHp}</div><div class="bar hp"><i style="width:${mhp}%"></i></div></div>
    </div>
    <div class="combat-log" id="clog">${[...G.combatLog].reverse().map(l=>`<div>${l}</div>`).join('')}</div>
    <div class="cbt-food">
      ${(_hasAutoEat && foods.length) ? `<div class="cbt-food-row"><label class="row tiny muted" style="gap:6px">Auto-eat:
          <select onchange="setCombatAutoEat(this.value)" style="background:rgba(255,255,255,.04);border:1px solid var(--line-soft);border-radius:6px;padding:5px 8px;color:var(--ink)">
            <option value="">Off</option>
            ${foods.map(([id])=>`<option value="${id}" ${(_eatCfg&&_eatCfg.foodId===id&&_eatCfg.enabled)?'selected':''}>${ITEMS[id].n} ×${G.inventory[id]}</option>`).join('')}
          </select>
        </label></div>` : ''}
      <div class="cbt-food-note tiny muted">${_foodNote}</div>
    </div>`;
  stop.style.display='inline-flex';
  /* Repaint the stage-side controls in the same turn, so a caller that renders
     and immediately reads (the smoke suite does exactly this) never sees a
     button one tick out of date. */
  if(window.HearthriseCombatHud) window.HearthriseCombatHud.refresh();
}
function renderLoadout(){
  const el=document.getElementById('loadout-panel');if(!el)return;
  migrateEquipmentSlots();
  const s=getEquipmentStats();
  el.innerHTML=`
    <div class="loadout-grid">
      ${EQUIP_SLOTS.slice(0,12).map(slot=>{
        const id=G.equipment[slot];const def=id?ITEMS[id]:null;const meta=EQUIP_SLOT_META[slot];
        return `<button class="loadout-slot ${def?'':'empty'}" onclick="${def?`unequip('${slot}')`:''}" title="${def?def.n+' (click to unequip)':meta.label}">${def?def.icon:meta.icon}<small>${def?def.n.split(' ')[0]:meta.label}</small></button>`;
      }).join('')}
    </div>
    <div class="stat-grid">
      <div class="stat"><b>+${s.atkB}</b><span>Atk</span></div>
      <div class="stat"><b>+${s.strB}</b><span>Str</span></div>
      <div class="stat"><b>+${s.defB}</b><span>Def</span></div>
      <div class="stat"><b>+${Math.round(s.critB*100)}%</b><span>Crit</span></div>
      <div class="stat"><b>+${Math.round(s.xpB*100)}%</b><span>XP</span></div>
      <div class="stat"><b>+${Math.round(s.spdB*100)}%</b><span>Spd</span></div>
      <div class="stat"><b>${WEAPON_TYPES[s.weaponType]}</b><span>Type</span></div>
    </div>
    <div class="muted tiny" style="margin-top:8px">Tap a slot to unequip. Manage gear from the Inventory tab.</div>`;
}
function unequip(slot){const id=G.equipment[slot];if(!id)return;G.equipment[slot]=null;G.inventory[id]=(G.inventory[id]||0)+1;notify(`Unequipped ${ITEMS[id].n}`,'info');renderLoadout();renderInventory();}
/* b246 (Tyler) — REAL GEAR LEVEL REQUIREMENTS. The flyout showed "Requires
   Lv X" but equipItem equipped anything — a phantom gate. Now armour is gated
   on Defence and weapons on their combat style, at the tier's level (Bronze 1 →
   Dawnsteel 88). GRANDFATHERED: anything a player already has worn is recorded
   (on load + on every successful equip) so no one is ever stripped of gear, and
   gear you've legitimately equipped once can always be re-worn. */
const _TIER_WIELD_LV=[0,1,15,30,45,60,75,88]; // by item.tier 1..7 (the tier gates)
function gearWieldReq(it){
  if(!it) return null;
  if(it.type!=='weapon' && it.type!=='armor' && it.type!=='jewelry') return null;
  let lv = (typeof it.reqLv==='number') ? it.reqLv : (it.tier ? (_TIER_WIELD_LV[it.tier]||0) : 0);
  if(!lv || lv<=1) return null;
  let skill = it.reqSkill;
  if(!skill){ skill = it.type==='armor' ? 'defense' : it.weaponType==='ranged' ? 'ranged' : it.weaponType==='magic' ? 'magic' : 'attack'; }
  return { skill, lv };
}
function canWield(id){
  const it=ITEMS[id]; const req=gearWieldReq(it);
  if(!req) return { ok:true };
  if(G.wieldGrandfather && G.wieldGrandfather[id]) return { ok:true };   // already-owned gear
  if(getLevel(req.skill) >= req.lv) return { ok:true };
  return { ok:false, req };
}
window.gearWieldReq=gearWieldReq; window.canWield=canWield;
function equipItem(id){
  migrateEquipmentSlots();
  const def=ITEMS[id];if(!def||(!def.type&&!def.slot))return;
  const w=canWield(id);   // b246: enforce the wield gate (grandfathered)
  if(!w.ok){ notify(`Requires ${(SKILLS_DEF[w.req.skill]&&SKILLS_DEF[w.req.skill].name)||w.req.skill} Lv ${w.req.lv} to wield ${def.n}`,'kill'); return; }
  const slot=getPreferredSlot(def);if(!slot||!EQUIP_SLOTS.includes(slot))return;
  const old=G.equipment[slot];if(old)G.inventory[old]=(G.inventory[old]||0)+1;
  G.equipment[slot]=id;removeItem(id,1);
  G.wieldGrandfather=G.wieldGrandfather||{}; G.wieldGrandfather[id]=true;   // once worn, always re-wearable
  notify(`Equipped ${def.n}`,'info');
  renderInventory();renderLoadout();
}

