/* What you actually receive, with the currency glyph rather than 💎 / 🪙. */
function _iapContents(p){
  if(!window.HR || !window.HR.amount) return '';
  var parts = [];
  if(p.gems) parts.push(window.HR.amount('gems', p.gems.toLocaleString(), 13, '--gem'));
  if(p.gold) parts.push(window.HR.amount('gold', p.gold.toLocaleString(), 13, '--gold-2'));
  if(p.tokens) parts.push(window.HR.amount('token', p.tokens, 13, '--gold-2'));
  return parts.length ? '<small>'+parts.join('')+'</small>' : '';
}
function renderShop(){
  /* IAP side (always visible) */
  document.getElementById('iap-panel').innerHTML=`
    <div class="iap-grid">
      ${IAP_CATALOG.map(p=>`
        <div class="iap-card ${p.style||''}">
          ${p.ribbon?`<div class="ribbon">${p.ribbon}</div>`:''}
          <div class="iap-icon">${_iapGlyph(p)}</div>
          <h3>${p.title}</h3>
          <div class="desc">${p.desc}</div>
          <div class="iap-foot">
            <div class="iap-price">${p.price}${_iapContents(p)}</div>
            <button class="btn btn-gem btn-sm" onclick="IAP.buy('${p.sku}')">Buy</button>
          </div>
        </div>`).join('')}
    </div>
    ${(G.inventory?.hearth_token||0)>0?`
    <div class="activity-card sc-token-card"><div class="ac-icon">${(window.HR&&window.HR.icon)?window.HR.icon('token',22,'--gold-2'):''}</div><div style="flex:1"><b>Hearth Tokens: ${G.inventory.hearth_token}</b><span>Sell on the player market for gold, or redeem here for 150 gems each.</span></div><button class="btn btn-sm btn-primary" onclick="redeemHearthToken()">Redeem 1 → 150 gems</button></div>`:''}
    <div class="muted tiny" style="margin-top:14px">Purchases route to the platform you're running on (Steamworks / App Store / Play Store / Stripe). Receipts are validated server-side before granting items. Detected: <b>${IAP.detectPlatform()}</b>.</div>`;

  /* in-game shop side */
  const el=document.getElementById('shop-panel');if(!el)return;
  let offers='';
  if(shopTab==='seeds'){
    offers=SEED_SHOP.map(s=>{const d=ITEMS[s.id];const can=G.gold>=s.cost;return `<div class="shop-row"><span class="si">${itemArt(s.id)}</span><div class="info"><b>${d.n} ×${s.qty}</b><span>Have: ${G.inventory[s.id]||0}</span></div><span class="price">${_gp(s.cost)}</span><button class="btn btn-sm ${can?'btn-primary':''}" ${can?'':'disabled'} onclick="buyShopItem('${s.id}',${s.qty},${s.cost})">Buy</button></div>`;}).join('');
  } else if(shopTab==='equip'){
    offers=EQUIP_SHOP.map(s=>{const d=ITEMS[s.id];const can=G.gold>=s.cost;const stats=[d.atkB?`+${d.atkB} ATK`:'',d.defB?`+${d.defB} DEF`:'',d.strB?`+${d.strB} STR`:''].filter(Boolean).join(' · ');return `<div class="shop-row"><span class="si">${itemArt(s.id)}</span><div class="info"><b>${d.n}</b><span>${stats||d.n}</span></div><span class="price">${_gp(s.cost)}</span><button class="btn btn-sm ${can?'btn-primary':''}" ${can?'':'disabled'} onclick="buyShopItem('${s.id}',1,${s.cost})">Buy</button></div>`;}).join('');
  } else {
    /* cosmetics — gem-priced.
       b221: these four shipped `icon:'✨' / '🐲' / '🦅' / '😎'` and rendered them
       straight into `.si` — four system-font emoji, live on the store screen,
       in a game whose first art rule is that emoji are never art. The strip
       sweep in icon-set.js only covers `#panel-bounty .si`, so nothing caught
       them. They now draw from the baked atlas like everything else. */
    const cosmetics=[
      {id:'name_gold',name:'Golden Name',glyph:'uiStar',price:200,desc:'Gold-tinted player name in chat & leaderboards.'},
      /* `dragon` lives in HR_MONSTER_GLYPHS, not HR_GLYPHS — HR.icon() resolves
         only the latter, so it drew nothing at all. navProfile is the portrait
         glyph, which is what this cosmetic actually changes. */
      {id:'avatar_dragon',name:'Dragon Avatar',glyph:'navProfile',price:500,desc:'Animated dragon profile portrait.'},
      {id:'pet_phoenix',name:'Phoenix Pet',glyph:'uiFire',price:1200,desc:'Idle phoenix companion (cosmetic).'},
      {id:'emote_pack',name:'Emote Pack',glyph:'uiChat',price:300,desc:'12 chat emotes for clan chat.'},
    ];
    offers=cosmetics.map(c=>{const owned=G.ownedCosmetics.includes(c.id);const can=(G.gems||0)>=c.price;const art=(window.HR&&window.HR.icon)?(window.HR.icon(c.glyph,30,'--gem')||''):'';return `<div class="shop-row"><span class="si is-prem">${art}</span><div class="info"><b>${c.name}</b><span>${c.desc}</span></div><span class="price gem">${_gem(c.price)}</span>${owned?'<button class="btn btn-sm" disabled>Owned</button>':`<button class="btn btn-sm ${can?'btn-gem':''}" ${can?'':'disabled'} onclick="buyCosmetic('${c.id}',${c.price})">Buy</button>`}</div>`;}).join('')+`<div class="sc-note">Need gems? <button class="btn btn-sm btn-gem" onclick="IAP.buy('gems_starter')">Get Gems</button></div>`;
  }
  /* b217: gold-purchased trait upgrades — appended below the tab list so
     they're reachable from the in-game shop. Reuses the existing shop-row
     component (no new styles). */
  const _traitRows=Object.entries(TRAITS).map(([id,t])=>{
    const owned=hasTrait(id);const can=t.currency==='marks'?((G.bountyHunter&&G.bountyHunter.marks||0)>=t.cost):((G.gold||0)>=t.cost);
    const art=(window.HR&&window.HR.icon)?window.HR.icon(t.glyph,30,'currentColor'):'';
    return `<div class="shop-row"><span class="si">${art}</span><div class="info"><b>${t.name}</b><span>${t.desc}</span></div>${owned?'<button class="btn btn-sm" disabled>Unlocked</button>':`<span class="price">${t.currency==='marks'?t.cost+' Marks':_gp(t.cost)}</span><button class="btn btn-sm ${can?'btn-primary':''}" ${can?'':'disabled'} onclick="buyTrait('${id}')">Buy</button>`}</div>`;
  }).join('');
  /* b221: the scene and the offers are ONE object — the counter's top surface
     runs out of the picture and under the wares. Assign once; the old code
     wrote innerHTML twice, which re-parsed and re-laid-out the whole list. */
  el.innerHTML=SHOP_SCENE
    +`<div class="sc-counter">${offers}`
    +`<div class="sc-sep">Under the counter</div>`+_traitRows
    +`</div>`;
}
function setShopTab(t){shopTab=t;document.querySelectorAll('[data-shop]').forEach(c=>c.classList.toggle('active',c.dataset.shop===t));renderShop();}
function buyShopItem(id,qty,cost){if(G.gold<cost){notify('Not enough gold','kill');return;}G.gold-=cost;addItem(id,qty);notify(`Bought ${qty}× ${ITEMS[id]?.n}`,'loot');updateTopbar();renderShop();}
function buyCosmetic(id,price){if((G.gems||0)<price){notify('Not enough gems. Tap "Get Gems".','kill');return;}G.gems-=price;G.ownedCosmetics.push(id);notify('Cosmetic unlocked!','levelup');saveLocal();updateTopbar();renderShop();}
/* b269: the "Buy space" dialog for the bank. Shows the live cap, the next gold
   cost (escalating) and the flat gem deal side-by-side so the better value of
   gems is legible. Reuses the .qm-overlay backdrop + .btn classes — no new CSS. */
function closeBankModal(){ var o=document.getElementById('bank-modal-overlay'); if(o)o.remove(); }
function _bankRowsHTML(){
  var used=bankUsed(), cap=bankCap();
  var gCost=bankGoldCost(), gemCost=BANK_SPACE.gem.cost;
  var canG=(G.gold||0)>=gCost, canGem=(G.gems||0)>=gemCost;
  var gp=(typeof _gp==='function')?_gp:function(n){return n.toLocaleString()+' gold';};
  var gem=(typeof _gem==='function')?_gem:function(n){return n.toLocaleString()+' gems';};
  var gemPerSlot=(gemCost/BANK_SPACE.gem.slots), goldPerSlot=(gCost/BANK_SPACE.gold.slots);
  return ''
    + '<p class="bank-cap-line">Bank space: <b>'+used+' / '+cap+'</b> stacks</p>'
    + '<div class="bank-opt">'
      + '<div class="bank-opt-info"><b>+'+BANK_SPACE.gold.slots+' stacks</b><span>Gold — cost rises with every purchase.</span></div>'
      + '<div class="bank-opt-buy"><span class="price">'+gp(gCost)+'</span>'
      + '<button class="btn btn-sm '+(canG?'btn-primary':'')+'" '+(canG?'':'disabled')+' onclick="buyBankSpaceGold()">Buy</button></div>'
    + '</div>'
    + '<div class="bank-opt bank-opt-gem">'
      + '<div class="bank-opt-info"><b>+'+BANK_SPACE.gem.slots+' stacks</b><span>Gems — a flat, better deal ('+goldPerSlot.toFixed(0)+' g/slot vs '+gemPerSlot.toFixed(2)+' gem/slot).</span></div>'
      + '<div class="bank-opt-buy"><span class="price gem">'+gem(gemCost)+'</span>'
      + '<button class="btn btn-sm '+(canGem?'btn-gem':'')+'" '+(canGem?'':'disabled')+' onclick="buyBankSpaceGem()">Buy</button></div>'
    + '</div>';
}
function _renderBankModal(){
  var body=document.getElementById('bank-modal-body');
  if(body) body.innerHTML=_bankRowsHTML();
}
function openBankModal(){
  closeBankModal();
  var overlay=document.createElement('div');
  overlay.className='qm-overlay'; overlay.id='bank-modal-overlay';
  overlay.innerHTML=
    '<div class="qm-modal bank-modal" style="position:relative;max-width:460px">'
    + '<button class="qm-close" aria-label="Close">✕</button>'
    + '<h3 style="margin:0 0 4px">Buy bank space</h3>'
    + '<div id="bank-modal-body">'+_bankRowsHTML()+'</div>'
    + '</div>';
  overlay.querySelector('.qm-close').addEventListener('click', closeBankModal);
  overlay.addEventListener('click', function(e){ if(e.target===overlay) closeBankModal(); });
  document.body.appendChild(overlay);
}
try{ window.openBankModal=openBankModal; window.closeBankModal=closeBankModal; }catch(_){}
/* b217: permanent trait upgrades bought with GOLD. Deliberately not free —
   early game is manual eating (click food in combat); players buy the
   convenience once they're established. Gate lives in
   HearthriseAuto.maybeAutoEat() so it can't be bypassed via the settings
   toggle. Data-driven so more QoL traits can be added later. */
const TRAITS={
  /* b227 (Tyler): auto-eat is earned at the bounty board, not bought with gold. */
  auto_eat:{name:'Auto-Eat',cost:100,currency:'marks',glyph:'meat',desc:'Automatically eat food in combat when your HP drops low. Earned with Bounty Marks — hunt bounties to afford it. Set the threshold in Settings → Gameplay.'},
};
window.TRAITS=TRAITS;
function hasTrait(id){return !!(G.traits&&G.traits[id]);}
window.hasTrait=hasTrait;
function buyTrait(id){
  const t=TRAITS[id];if(!t)return;
  if(hasTrait(id)){notify('Already unlocked','info');return;}
  if(t.currency==='marks'){
    const bh=G.bountyHunter||{};
    if((bh.marks||0)<t.cost){notify('Not enough Bounty Marks — hunt bounties to earn them','kill');return;}
    bh.marks-=t.cost;
  } else {
    if((G.gold||0)<t.cost){notify('Not enough gold','kill');return;}
    G.gold-=t.cost;
  }
  G.traits=G.traits||{};
  G.traits[id]=true;
  // Buying auto-eat turns it on so it works immediately; threshold stays default.
  if(id==='auto_eat'&&window.HearthriseAuto&&typeof window.HearthriseAuto.setEat==='function'){
    window.HearthriseAuto.setEat({enabled:true});
  }
  notify(`Unlocked ${t.name}!`,'levelup');
  if(typeof saveLocal==='function')saveLocal();
  if(typeof updateTopbar==='function')updateTopbar();
  if(typeof renderShop==='function')renderShop();
}
window.buyTrait=buyTrait;

/* ────────────────────────────────────────────────
   SETTINGS modal
   ──────────────────────────────────────────────── */
function openSettings(){
  const m=document.getElementById('settings-modal');
  document.getElementById('settings-body').innerHTML=`
    <div class="muted tiny" style="text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px">Account</div>
    ${G.account?
      `<div class="activity-card"><div class="ac-icon">👤</div><div style="flex:1"><b>${escapeHtml(G.account.displayName)}</b><span>Provider: ${G.account.provider}</span></div><button class="btn btn-sm btn-danger" onclick="NetClient.signOut();openSettings()">Sign out</button></div>`:
      `<div class="kpi-row" style="margin-bottom:14px">
        <button class="btn tap" onclick="NetClient.signIn('steam').then(()=>openSettings())">Sign in (Steam)</button>
        <button class="btn tap" onclick="NetClient.signIn('apple').then(()=>openSettings())">Sign in (Apple)</button>
        <button class="btn tap" onclick="NetClient.signIn('google').then(()=>openSettings())">Sign in (Google)</button>
        <button class="btn tap" onclick="NetClient.signIn('guest').then(()=>openSettings())">Continue as guest</button>
      </div>`}

    <div class="muted tiny" style="text-transform:uppercase;letter-spacing:.08em;margin:14px 0 6px">Display name</div>
    <div class="row" style="gap:8px"><input type="text" value="${escapeHtml(G.playerName)}" id="set-name" style="flex:1;background:rgba(255,255,255,.04);border:1px solid var(--line-soft);border-radius:8px;padding:8px 10px"><button class="btn" onclick="G.playerName=document.getElementById('set-name').value||'Adventurer';updateTopbar();notify('Name updated','info')">Save</button></div>

    <div class="muted tiny" style="text-transform:uppercase;letter-spacing:.08em;margin:14px 0 6px">Game</div>
    <label class="row tap" style="gap:8px;padding:6px 0"><input type="checkbox" ${G.settings.sfx?'checked':''} onchange="G.settings.sfx=this.checked;saveLocal()"> Sound effects</label>
    <label class="row tap" style="gap:8px;padding:6px 0"><input type="checkbox" ${G.settings.reduceFx?'checked':''} onchange="G.settings.reduceFx=this.checked;saveLocal();document.documentElement.style.setProperty('--reduce-fx',this.checked?'1':'0')"> Reduce visual effects</label>
    <label class="row tap" style="gap:8px;padding:6px 0"><input type="checkbox" ${G.settings.leftHand?'checked':''} onchange="G.settings.leftHand=this.checked;saveLocal()"> Left-handed mode (mobile)</label>

    <div class="muted tiny" style="text-transform:uppercase;letter-spacing:.08em;margin:14px 0 6px">Save data</div>
    <div class="kpi-row">
      <button class="btn tap" onclick="saveLocal();notify('Saved','info')">💾 Save now</button>
      <button class="btn tap" onclick="cloudSync()">☁️ Cloud sync</button>
      <button class="btn tap" onclick="exportSave()">⬇️ Export</button>
      <button class="btn tap btn-danger" onclick="if(confirm('Erase save?')){if(window.HearthriseStorage){window.HearthriseStorage.remove(SAVE_KEY);}else{localStorage.removeItem(SAVE_KEY);}location.reload();}">🗑️ Reset</button>
    </div>
    <div class="muted tiny" style="margin-top:8px">Last cloud sync: ${G.cloudSyncedAt?new Date(G.cloudSyncedAt).toLocaleString():'never'}.</div>

    <div class="muted tiny" style="text-transform:uppercase;letter-spacing:.08em;margin:14px 0 6px">Shortcuts</div>
    <div class="muted tiny">1-8: tabs · S: save · Esc: close modals · Arrow keys: nav focus</div>`;
  m.classList.add('show');
}
async function cloudSync(){
  if(!G.account){notify('Sign in first','kill');return;}
  const r=await NetClient.cloudSync();
  notify(r.ok?'Cloud saved ☁️':'Cloud save failed','info');
  openSettings();
}
function exportSave(){
  const data=btoa(unescape(encodeURIComponent(JSON.stringify(G))));
  try{navigator.clipboard?.writeText(data);notify('Save exported to clipboard','info');}
  catch(e){prompt('Copy your save:',data);}
}

/* ────────────────────────────────────────────────
   helpers
   ──────────────────────────────────────────────── */
function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}

/* ════════════════════════════════════════════════
   INPUT / EVENTS
   ════════════════════════════════════════════════ */
function bindEvents(){
  /* nav */
  document.querySelectorAll('.nav-btn,.bn-btn').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));
  /* tier chips */
  document.querySelectorAll('#tier-chips .chip').forEach(c=>c.addEventListener('click',()=>selectTier(+c.dataset.tier)));
  /* inv tabs */
  document.querySelectorAll('[data-inv]').forEach(c=>c.addEventListener('click',()=>{invTab=c.dataset.inv;document.querySelectorAll('[data-inv]').forEach(x=>x.classList.toggle('active',x===c));renderInventory();}));
  /* house tabs */
  document.querySelectorAll('[data-house]').forEach(c=>c.addEventListener('click',()=>setHouseTab(c.dataset.house)));
  /* lb tabs */
  document.querySelectorAll('[data-lb]').forEach(c=>c.addEventListener('click',()=>setLbMode(c.dataset.lb)));
  /* shop tabs */
  document.querySelectorAll('[data-shop]').forEach(c=>c.addEventListener('click',()=>setShopTab(c.dataset.shop)));
  /* combat stop */
  document.getElementById('combat-stop').addEventListener('click',stopCombat);
  /* topbar buttons */
  /* b227: manual save button removed — online realm, autosave + sync own persistence */
  document.getElementById('btn-settings').addEventListener('click',openSettings);
  document.getElementById('btn-settings-mobile')?.addEventListener('click',()=>{document.getElementById('more-modal').classList.remove('show');openSettings();});
  document.getElementById('combat-gear-btn').addEventListener('click',()=>showTab('inventory'));
  /* b230: the topbar gem counter means "I want gems" — it opens the Premium
     Shop toggle directly, not the shop's front door. */
  document.getElementById('top-gem-btn').addEventListener('click',()=>showTab('premium'));
  /* modals close */
  document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.closeModal).classList.remove('show')));
  document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('show');}));
  /* keyboard shortcuts */
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'){document.querySelectorAll('.modal.show').forEach(m=>m.classList.remove('show'));return;}
    if(e.target.matches('input,textarea,select'))return;
    const map={'1':'profile','2':'combat','3':'skills','4':'inventory','5':'farming','6':'house','7':'social','8':'shops'};
    if(map[e.key]){showTab(map[e.key]);e.preventDefault();}
    if(e.key.toLowerCase()==='s'){saveLocal();notify('Saved 💾','info');}
  });
  /* online/offline events */
  window.addEventListener('online',updateNetStatus);
  window.addEventListener('offline',updateNetStatus);
  /* visibility — save on hide, catch up on resume.
     b229 (paione, mobile): on a phone "logging off" means backgrounding the app
     or locking the screen — the page is NOT reloaded, so loadLocal()/processOffline()
     never re-run. Mobile freezes all timers while backgrounded, so an active
     gather/smith/fight makes ZERO progress and nothing credits it on return —
     "it doesn't keep collecting ore." Desktop hid this because background tabs
     keep ticking (throttled). Fix: when the tab becomes visible again, run the
     same offline catch-up a fresh load would. processOffline() is idempotent —
     its watermark (offlineBudget.at, set to now by the saveLocal on hide) means
     it credits the frozen span exactly once and early-returns under ~3min, so a
     quick tab-flip costs nothing. */
  /* b260 — ROBUST RESUME. b258 re-armed combat on visibilitychange, but paione
     still saw frozen offline/afk combat: iOS PWAs do NOT reliably fire
     visibilitychange on return (they may fire pageshow/focus, or nothing). So:
       1. Every resume signal funnels through one idempotent handler.
       2. A platform-independent WATCHDOG re-runs it every few seconds, so even
          if NO resume event fires, a frozen span gets credited and a dead loop
          gets re-armed within seconds of the tab being active again.
     processOffline() is idempotent and early-returns under ~3min (its watermark
     only grants for a real gap), so running it often is cheap and safe. */
  function hrResume(){
    try{ if(window.HearthriseGate && !window.HearthriseGate.isOpen()) return; }catch(e){}
    // No debounce: several signals fire on one return, but processOffline() is
    // idempotent (its watermark credits a span exactly once) and
    // resumeActiveActivity() is guarded, so redundant calls are cheap and safe.
    try{ if(typeof processOffline==='function') processOffline(); }catch(e){}
    try{ if(typeof resumeActiveActivity==='function') resumeActiveActivity(); }catch(e){}
    try{ if(typeof refreshAll==='function') refreshAll(); }catch(e){}
  }
  window.__hrResume=hrResume;
  document.addEventListener('visibilitychange',()=>{
    if(document.hidden){ try{ saveLocal(); }catch(e){} return; }
    hrResume();
  });
  /* iOS PWA / bfcache restore and app-switch return often fire these INSTEAD of
     visibilitychange. All funnel to the same idempotent handler. */
  window.addEventListener('pageshow',()=>hrResume());
  window.addEventListener('focus',()=>hrResume());
  document.addEventListener('resume',()=>hrResume());   // Capacitor/Cordova wrapper
  window.addEventListener('pagehide',()=>{ try{ saveLocal(); }catch(e){} });
  /* The net that doesn't depend on any event firing: re-arm dead loops + credit a
     frozen span on the first ticks after the tab is active again. Guarded so it's
     a no-op while everything is already running. NOT started under the test
     harness — a 4s timer mutating G would race the smoke suite's controlled
     setups (the __hrResume logic is exercised directly by the b260 test instead). */
  if(!window.__HR_TEST_HARNESS__){
    setInterval(()=>{
      try{
        if(typeof G==='undefined'||!G) return;
        if(typeof document!=='undefined' && document.hidden) return;   // b261: do nothing while backgrounded — its job is to catch up AFTER return
        if(window.HearthriseGate && !window.HearthriseGate.isOpen()) return;
        // A combat loop counts as broken if it's NULL *or* STALLED — a mobile
        // background freeze suspends the interval without clearing it, so a bare
        // null-check misses it. Use the heartbeat (window._hrCombatBeat), same as
        // resumeActiveActivity, so the watchdog fixes a frozen fight even when no
        // resume event ever fires.
        const beatStale  = (Date.now() - (window._hrCombatBeat||0)) > 8000;
        const combatBad  = G.activeMonster && (
          (typeof window.__isCombatLoopArmed==='function' && !window.__isCombatLoopArmed()) || beatStale);
        const skillDead  = G.activeSkill && typeof window.__isSkillLoopArmed==='function' && !window.__isSkillLoopArmed();
        // Credit any real elapsed gap (idempotent; early-returns for small gaps),
        // and re-arm whichever live loop died or stalled.
        if(typeof processOffline==='function') processOffline();
        if((combatBad||skillDead) && typeof resumeActiveActivity==='function') resumeActiveActivity();
      }catch(e){}
    }, 4000);
  }
}

/* ════════════════════════════════════════════════
   PWA — manifest + service worker (single file)
   ════════════════════════════════════════════════ */
function installPwa(){
  /* inject manifest */
  const manifest={
    name:'Hearthrise — Idle Homestead',
    short_name:'Hearthrise',
    description:'Idle homestead RPG — fight, farm, craft, build a home.',
    start_url:'./',
    display:'fullscreen',
    orientation:'any',
    // b108: switched from old dark navy to cozy parchment palette so the
    // installed-PWA splash screen + status bar match the in-game UI.
    background_color:'#fff8e2',     // parchment cream
    theme_color:'#5c2d08',           // cocoa
    categories:['games','entertainment'],
    icons:[
      // Real Hearthrise crest instead of emoji square. Available on the
      // deploy at assets/brand/hearthrise-logo.svg.
      {src:'assets/brand/hearthrise-logo.svg', sizes:'any', type:'image/svg+xml', purpose:'any'},
      {src:'assets/brand/hearthrise-logo.svg', sizes:'192x192', type:'image/svg+xml'},
      {src:'assets/brand/hearthrise-logo.svg', sizes:'512x512', type:'image/svg+xml'},
    ],
  };
  const blob=new Blob([JSON.stringify(manifest)],{type:'application/manifest+json'});
  const url=URL.createObjectURL(blob);
  const link=document.createElement('link');link.rel='manifest';link.href=url;document.head.appendChild(link);

  /* register service worker (only if served over http/https)
   *
   * b111: rewrote the strategy. The old SW used a fixed cache name
   * (`hearthbound-v2`) and "cache-first" for everything, which meant
   * any file the SW had ever seen got served from cache forever —
   * pushing a new build did nothing for installed PWAs until the user
   * manually deleted + reinstalled the home shortcut.
   *
   * New strategy:
   *  • Cache name = `hearthrise-${BUILD}` derived from the cache-buster
   *    on this page's <script> tags. New build → new cache name → old
   *    caches purged on activate.
   *  • App shell (HTML/JS/CSS) = network-first. Try fetch; on success,
   *    update cache + serve. On failure, fall back to cache (offline).
   *  • Static assets (images/fonts) = cache-first. They're versioned
   *    by URL anyway, so cache hits are safe.
   *  • skipWaiting() + clients.claim() so the new SW takes control
   *    immediately without requiring a page close. */
  if('serviceWorker' in navigator && /^https?:/.test(location.protocol)){
    /* Extract the active build version from any of our versioned <script>
     * tags. e.g. legacy.js?v=111 → "111". Fallback "0" if not found. */
    const verMatch = (function(){
      const scripts = document.querySelectorAll('script[src*="?v="]');
      for (const s of scripts){
        const m = s.src.match(/\?v=(\d+)/);
        if (m) return m[1];
      }
      return '0';
    })();
    const swCode = `
      const BUILD = '${verMatch}';
      const CACHE = 'hearthrise-' + BUILD;
      const SHELL = ['./','./index.html'];

      function isShell(req){
        const u = new URL(req.url);
        if (u.origin !== self.location.origin) return false;
        const p = u.pathname;
        return p === '/' || p.endsWith('/') || p.endsWith('.html')
            || p.endsWith('.js') || p.endsWith('.css') || p.endsWith('.json');
      }
      function isStatic(req){
        const u = new URL(req.url);
        if (u.origin !== self.location.origin) return false;
        const p = u.pathname;
        return p.endsWith('.png') || p.endsWith('.jpg') || p.endsWith('.jpeg')
            || p.endsWith('.svg') || p.endsWith('.webp') || p.endsWith('.woff2')
            || p.endsWith('.woff') || p.endsWith('.ttf');
      }

      self.addEventListener('install', e => {
        // Pre-cache the app shell so cold-start works offline.
        e.waitUntil(
          caches.open(CACHE).then(c => c.addAll(SHELL).catch(()=>{}))
        );
        self.skipWaiting();
      });

      self.addEventListener('activate', e => {
        // Purge any old hearthrise-* caches from previous builds.
        e.waitUntil((async () => {
          const keys = await caches.keys();
          await Promise.all(keys.map(k => {
            if (k !== CACHE && (k.startsWith('hearthrise-') || k === 'hearthbound-v2')) {
              return caches.delete(k);
            }
          }));
          await self.clients.claim();
        })());
      });

      self.addEventListener('fetch', e => {
        const req = e.request;
        if (req.method !== 'GET') return;

        if (isShell(req)) {
          // Network-first for app shell — try fresh, fall back to cache offline.
          e.respondWith((async () => {
            try {
              const res = await fetch(req);
              try { (await caches.open(CACHE)).put(req, res.clone()); } catch {}
              return res;
            } catch {
              const cached = await caches.match(req);
              if (cached) return cached;
              return caches.match('./');
            }
          })());
          return;
        }

        if (isStatic(req)) {
          // Cache-first for images/fonts — versioned by URL, safe to cache.
          e.respondWith((async () => {
            const cached = await caches.match(req);
            if (cached) return cached;
            try {
              const res = await fetch(req);
              try { (await caches.open(CACHE)).put(req, res.clone()); } catch {}
              return res;
            } catch {
              return new Response('', { status: 504 });
            }
          })());
          return;
        }

        // Anything else (cross-origin Supabase, CDN imports): pass through.
      });
    `;
    const swBlob = new Blob([swCode], {type:'text/javascript'});
    const swUrl  = URL.createObjectURL(swBlob);
    navigator.serviceWorker.register(swUrl).catch(()=>{});
  }

  /* iOS / Android install prompt hint */
  let deferredPrompt=null;
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;
    /* only nudge once per session */
    if(!sessionStorage.getItem('install-prompted')){
      sessionStorage.setItem('install-prompted','1');
      setTimeout(()=>{
        const ok=confirm('Install Hearthrise to your home screen for full-screen play?');
        if(ok&&deferredPrompt){deferredPrompt.prompt();}
      },5000);
    }
  });
}

/* ════════════════════════════════════════════════
   BOOT
   ════════════════════════════════════════════════ */
function boot(){
  loadLocal();
  bindEvents();
  installPwa();
  updateTopbar();
  updateNetStatus();
  showTab('profile');
  startFarmCheck();
  /* auto-save every 90 seconds */
  setInterval(()=>{saveLocal();},90000);
  /* expose dev helpers */
  window.G=G;window.IAP=IAP;window.NetClient=NetClient;window.generateBountyBoard=generateBountyBoard;
  window.testerBoost=()=>{G.gold+=5000;G.gems+=200;ensureBountyState();G.bountyHunter.marks+=50;['turnip_seed','carrot_seed','wheat_seed','potato_seed'].forEach(id=>G.inventory[id]=(G.inventory[id]||0)+10);['normal_log','copper_ore','iron_ore','shrimp','bones'].forEach(id=>G.inventory[id]=(G.inventory[id]||0)+25);['woodcutting','mining','fishing','farming','attack','strength','defense'].forEach(sk=>G.skills[sk]=(G.skills[sk]||0)+650);G.skills.hitpoints=Math.max(G.skills.hitpoints||0,1584);G.playerMaxHp=levelFromXp(G.skills.hitpoints);G.playerHp=G.playerMaxHp;notify('Tester boost applied','loot');refreshAll();};
}
/* b224 ACCOUNT WALL — the engine does not start behind the gate.
   Everything that makes the game PROGRESS is started from boot(): loadLocal()
   (which runs processOffline() and resumes the combat tick), startFarmCheck(),
   and the 90-second autosave. Deferring this one call is therefore what makes
   "no gameplay behind the wall" true rather than merely painted over — there
   is no offline catch-up, no tick, and no write to the save while the player
   is at the door. The gate opens by reloading with a live session, so in the
   normal path this deferral simply never resumes; whenOpen() is still honest
   about running it if it ever does. */
(function(){
  function bootWhenReady(){
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);
    else boot();
  }
  if(window.HearthriseGate&&typeof window.HearthriseGate.whenOpen==='function')window.HearthriseGate.whenOpen(bootWhenReady);
  else bootWhenReady();
})();

