  // Insert before next group label or at end of homestead section
  var insertBefore = homesteadLabel.nextElementSibling;
  while(insertBefore && !insertBefore.classList.contains('nav-group-label') && !insertBefore.classList.contains('nav-spacer')){
    insertBefore = insertBefore.nextElementSibling;
  }
  if(insertBefore) sidebar.insertBefore(btn, insertBefore);
