// ===== block 35: companions-acquisition-js =====
(function(){
"use strict";

/* Drop-rate map (per design doc). Keyed by companion id. */
var DROP_CHANCES = {
  wolf_pup: 0.01,      // small_wolf 1%
  badger:   0.005,     // bear 0.5%
  hawk:     0.01,      // panther 1%
  scorpion: 0.005,     // shadow_creeper 0.5%
  tortoise: 0.005,     // ancient_bear 0.5%
};

function parseSource(src){
  if(!src) return null;
  var parts = src.split(':');
  return {kind: parts[0], arg1: parts[1], arg2: parts[2]};
}

/* On kill, check drop sources */
(function hookKillForDrops(){
  if(typeof window.killMonster !== 'function') return;
  var orig = window.killMonster;
  window.killMonster = function(m){
    var r = orig.apply(this, arguments);
    /* m may be the monster id string or object */
    var monsterId = (typeof m === 'string') ? m : (m && (m.id || m.key));
    if(!monsterId && typeof MONSTERS === 'object'){
      // Reverse-lookup: find the key whose value matches this monster object
      for(var k in MONSTERS){ if(MONSTERS[k] === m){ monsterId = k; break; } }
    }
    if(!monsterId || !window.COMPANIONS) return r;
    Object.entries(window.COMPANIONS).forEach(function(kv){
      var id = kv[0], def = kv[1];
      var src = parseSource(def.source);
      if(!src || src.kind !== 'drop') return;
      if(src.arg1 !== monsterId) return;
      /* Skip if already owned */
      if(G.companions && G.companions.ownedIds && G.companions.ownedIds.indexOf(id) >= 0) return;
      var chance = DROP_CHANCES[id] !== undefined ? DROP_CHANCES[id] : 0.01;
      if(Math.random() < chance){
        if(typeof window.unlockCompanion === 'function'){
          window.unlockCompanion(id);
          /* Big toast */
          try{
            var t = document.createElement('div');
            t.textContent = '🎉 New companion unlocked: '+def.icon+' '+def.n+'!';
            t.style.cssText = 'position:fixed;top:80px;left:50%;transform:translateX(-50%);z-index:99999;'+
              'background:linear-gradient(180deg,#7f9a4f,#3a8a52);color:#fff;padding:14px 22px;border-radius:8px;'+
              'font-weight:800;font-size:calc(16px * var(--ui-scale, 1));box-shadow:0 8px 32px rgba(0,0,0,.5);'+
              'border:2px solid #f3d181;animation:bigtoast 4s ease-out forwards';
            document.body.appendChild(t);
            setTimeout(function(){t.remove();}, 4500);
          }catch(e){}
        }
      }
    });
    return r;
  };
  /* Animation */
  if(!document.getElementById('comp-bigtoast-css')){
    var s = document.createElement('style');
    s.id = 'comp-bigtoast-css';
    s.textContent = '@keyframes bigtoast{0%{opacity:0;transform:translate(-50%,-20px)}15%{opacity:1;transform:translate(-50%,0)}80%{opacity:1}100%{opacity:0;transform:translate(-50%,20px)}}';
    document.head.appendChild(s);
  }
})();

/* Try to add companion entries to the in-game shop's Equipment tab */
(function injectShopCompanions(){
  function tryInject(){
    var shopPanel = document.querySelector('#panel-shop, #shop-panel');
    if(!shopPanel) return;
    /* Find the Equipment tab/section. The renderShop builds tabs (Seeds/Equipment/Cosmetics). */
    /* Detect if we're on Equipment tab */
    var activeTab = shopPanel.querySelector('button.active, .chip.active');
    if(!activeTab || !/equipment/i.test(activeTab.textContent)) return;
    /* Find where to append */
    var listContainer = shopPanel.querySelector('#shop-list, .shop-list, [id$="-list"]') || shopPanel.querySelector('.shop-row')?.parentElement;
    if(!listContainer) return;
    /* Already injected? */
    if(listContainer.querySelector('.shop-row[data-companion]')) return;
    /* Build companion shop rows */
    var companions = Object.entries(window.COMPANIONS||{}).filter(function(kv){
      var s = parseSource(kv[1].source);
      return s && s.kind === 'shop';
    });
    companions.forEach(function(kv){
      var id = kv[0], def = kv[1];
      var s = parseSource(def.source);
      var price = parseInt(s.arg1, 10);
      var skillReq = s.arg2; // e.g., "cooking25" or "prayer50"
      var owned = G.companions && G.companions.ownedIds && G.companions.ownedIds.indexOf(id) >= 0;
      var meetsReq = true, reqText = '';
      if(skillReq){
        var m = skillReq.match(/^(\w+?)(\d+)$/);
        if(m){
          var skill = m[1], lv = parseInt(m[2], 10);
          var have = (typeof getLevel === 'function') ? getLevel(skill) : 1;
          meetsReq = have >= lv;
          reqText = ' · req Lv '+lv+' '+skill;
        }
      }
      var row = document.createElement('div');
      row.className = 'shop-row';
      row.setAttribute('data-companion', id);
      row.innerHTML = '<span class="si">'+window.companionIconHtml(id, 28)+'</span>'
        + '<div class="info"><b>'+def.n+'</b><span>'+def.role+' companion'+reqText+'</span></div>'
        + (owned
            ? '<span class="tag" style="color:#7f9a4f">Owned</span>'
            : (meetsReq
                ? '<button class="btn btn-sm" onclick="window._buyCompanion(\''+id+'\','+price+')" style="background:#7f9a4f;color:#0f1320;font-weight:700">'+price+'g · Buy</button>'
                : '<span class="muted tiny">🔒 '+reqText+'</span>'
              )
          );
      listContainer.appendChild(row);
    });
  }
  /* Inject on shop tab click + after each renderShop */
  setInterval(tryInject, 1500);
})();

window._buyCompanion = function(id, price){
  if(G.gold < price){ if(typeof notify==='function') notify('Not enough gold','kill'); return; }
  if(G.companions && G.companions.ownedIds.indexOf(id) >= 0){ if(typeof notify==='function') notify('Already owned','info'); return; }
  G.gold -= price;
  if(typeof window.unlockCompanion === 'function') window.unlockCompanion(id);
  if(typeof updateTopbar === 'function') updateTopbar();
  if(typeof renderShop === 'function') renderShop();
};

/* Hatch dragon egg → Whelp companion */
(function hookEggUse(){
  /* Add a "Hatch" action on dragon_egg item if it gets used. */
  var origInvTap = window.invItemTap;
  if(typeof origInvTap !== 'function') return;
  window.invItemTap = function(id){
    if(id === 'dragon_egg' && G.inventory && G.inventory.dragon_egg > 0){
      if(confirm('Hatch a Dragon Egg to gain a Whelp companion?')){
        G.inventory.dragon_egg--;
        if(window.unlockCompanion) window.unlockCompanion('whelp');
        if(typeof renderInvFancy==='function') renderInvFancy();
        return;
      }
    }
    return origInvTap.apply(this, arguments);
  };
})();

/* Bunny quest: harvest 100 crops -> unlock */
(function hookBunnyQuest(){
  var origHarvest = window.harvestPlot;
  if(typeof origHarvest !== 'function') return;
  window.harvestPlot = function(){
    var r = origHarvest.apply(this, arguments);
    G.stats = G.stats || {};
    G.stats.cropsHarvested = (G.stats.cropsHarvested||0) + 1;
    if(G.stats.cropsHarvested >= 100 && G.companions && G.companions.ownedIds.indexOf('bunny') < 0){
      if(window.unlockCompanion) window.unlockCompanion('bunny');
    }
    return r;
  };
})();

console.log('[Companions D: acquisition] wired — drops, shop, hatch, quest');
})();

// ===== block 36: buff-queue-js =====
(function(){
"use strict";

// ── Buff type registry ──
// Maps buff.type → {label, bonusKey, isPercent}
// bonusKey is the key getBonus(key) callers use; isPercent governs display.
const BUFFS_DEF = {
  // Icons chosen to render unambiguously on Windows (Segoe UI Emoji) and
  // macOS (Apple Color Emoji) — avoid the abstract chart/graph emoji which
  // render as similar-looking multicolor blocks on both.
  gather_speed:    {label:'Gather Speed',     bonusKey:'gatherSpeed',    isPercent:true, icon:'🌿'},
  all_xp:          {label:'All XP',           bonusKey:'allXP',          isPercent:true, icon:'⭐'},
  drop_rate:       {label:'Drop Rate',        bonusKey:'dropRate',       isPercent:true, icon:'🍀'},
  /* b228: `farmYield` is a COUNT of extra crops, never a percentage — the
     blessing calendar has always granted it as "+2 farm yield". This entry
     claimed isPercent and getBuffBonuses divided its magnitude by 100, so
     Carrot Stew's "15" reached the engine as 0.15 of a crop and harvestPlot
     floored it to nothing. It is flat now, in both the maths and the label. */
  farm_yield:      {label:'Farm Yield',       bonusKey:'farmYield',      isPercent:false, isFlat:true, icon:'🌾'},
  damage:          {label:'Damage',           bonusKey:'damage',         isPercent:true, icon:'⚔️'},
  /* b238 (itemization Wave 1): `defense` was declared on Frostfin Supper but was
     NOT a key here, so applyBuff() rejected it and the tooltip promised a buff
     the engine threw away. It is a FLAT bump to your defence stat (a +4 food buff
     reads as "+4", not "+4%"), wired into playerDefense in getMonsterCombatRolls. */
  defense:         {label:'Defense',           bonusKey:'defense',        isPercent:false, isFlat:true, icon:'🛡️'},
  /* b238: `monster_respawn` was dead — this engine re-attacks instantly, there is
     no respawn timer to speed up. Removed; the two foods that used it (Tomato
     Soup, Hunter's Feast) are repointed to drop_rate, which is now live. */
  combat_xp:       {label:'Combat XP',        bonusKey:'combatXP',       isPercent:true, icon:'🗡️'},
  gold_find:       {label:'Gold Find',        bonusKey:'goldFind',       isPercent:true, icon:'💰'},
  damage_crit:     {label:'Critical Chance',  bonusKey:'crit',           isPercent:true, icon:'💥'},
};
window.BUFFS_DEF = BUFFS_DEF;

// ── State init ──
function ensureBuffState(){
  if(typeof G === 'undefined') return;
  if(!Array.isArray(G.buffs)) G.buffs = [];
}

/* ════════════════════════════════════════════════════════════════
   b222 (SEAM 2) — the timed-buff scaling choke-point.

   clan-overhaul v2 §9.1: the castle Tavern's Hearth lengthens food buffs by
   +4% per Tavern level and strengthens them by +2% per level (→ +40% / +20% at
   L10). applyBuff() had no hook for either, and the obvious "just multiply at
   the call site" fix would have meant editing every future caller — eatFood,
   the Feast, the Cellar draws, world-event blessings — and getting one wrong.

   So: ONE registry, consulted once, inside applyBuff. Scalers are NAMED, which
   makes registration idempotent (re-registering the same name replaces rather
   than compounds — a boot retry can never double a player's buff durations).
   Composition is multiplicative across scalers.

   Default is exactly 1.0 × 1.0: with nothing registered this is a no-op, and a
   regression test asserts both the identity default and that a stubbed scaler
   moves duration AND magnitude.

   Scale is applied at APPLICATION time, not at tick time. A buff you drank
   under a level-10 Tavern keeps the length it was poured with, even if the
   Tavern is later dimmed by unpaid upkeep — the alternative silently shortens
   an effect the player is already watching count down.
   ════════════════════════════════════════════════════════════════ */
const BUFF_SCALERS = Object.create(null);
window.registerBuffScaler = function(name, fn){
  if(typeof name !== 'string' || !name) throw new Error('registerBuffScaler: a name is required');
  if(typeof fn !== 'function') throw new Error('registerBuffScaler: fn must be a function');
  BUFF_SCALERS[name] = fn;
  return true;
};
window.unregisterBuffScaler = function(name){ delete BUFF_SCALERS[name]; };
// → {duration, magnitude} multipliers for this buff. Never returns < 0.
window.buffScaleFor = function(buff){
  let duration = 1, magnitude = 1;
  for(const name in BUFF_SCALERS){
    let s = null;
    try { s = BUFF_SCALERS[name](buff); } catch(e){ s = null; }
    if(!s || typeof s !== 'object') continue;
    if(typeof s.duration === 'number' && isFinite(s.duration) && s.duration >= 0) duration *= s.duration;
    if(typeof s.magnitude === 'number' && isFinite(s.magnitude) && s.magnitude >= 0) magnitude *= s.magnitude;
  }
  return { duration: duration, magnitude: magnitude };
};

// ── Public API ──

// Add a buff to the queue. If a buff of the same TYPE is already active,
// extend it: take the larger magnitude, add durations.
window.applyBuff = function(buff){
  ensureBuffState();
  if(!buff || !buff.type || !BUFFS_DEF[buff.type]) return false;
  const def = BUFFS_DEF[buff.type];
  /* b222 SEAM 2 — scale before the queue ever sees it, so the merge branch
     below extends by the SCALED duration too. */
  const scale = window.buffScaleFor(buff);
  const dur = Math.round((buff.durationMs||0) * scale.duration);
  const mag = (buff.magnitude||0) * scale.magnitude;
  const existing = G.buffs.find(b => b.type === buff.type);
  if(existing){
    existing.remainingMs = (existing.remainingMs||0) + dur;
    existing.magnitude = Math.max(existing.magnitude||0, mag);
  } else {
    G.buffs.push({
      type: buff.type,
      magnitude: mag,
      remainingMs: dur,
      addedAt: Date.now(),
    });
  }
  if(typeof window.renderActiveEffects === 'function') window.renderActiveEffects();
  if(window.HearthriseEvents) window.HearthriseEvents.emit('buffApply', {type:buff.type, magnitude:mag, durationMs:dur});
  return true;
};

// Aggregate active buffs into a {bonusKey: totalPercentDelta} map
window.getBuffBonuses = function(){
  ensureBuffState();
  const out = {};
  for(const b of G.buffs){
    if(b.remainingMs <= 0) continue;
    const def = BUFFS_DEF[b.type];
    if(!def) continue;
    /* b228: a FLAT key's magnitude is already in its own units (crops), so it
       is added as-is; every other key is a percentage stored as an integer. */
    out[def.bonusKey] = (out[def.bonusKey]||0) + (def.isFlat ? b.magnitude : b.magnitude/100);
  }
  return out;
};

// Remove expired buffs from queue
window.pruneBuffs = function(){
  ensureBuffState();
  const before = G.buffs.length;
  G.buffs = G.buffs.filter(b => b.remainingMs > 0);
  if(G.buffs.length !== before && typeof window.renderActiveEffects === 'function'){
    window.renderActiveEffects();
  }
};

// Force-eat a food item from inventory, applying its buff (if any) and heal.
// This is what the "Eat Now" button calls and is also the path auto-eat takes.
window.eatFood = function(foodId, opts){
  opts = opts || {};
  if(!G.inventory || (G.inventory[foodId]||0) <= 0) return false;
  const fd = (typeof ITEMS !== 'undefined') ? ITEMS[foodId] : null;
  if(!fd) return false;

  const info = (typeof window.foodUseInfo === 'function') ? window.foodUseInfo(foodId) : null;

  /* b224: refuse to burn a Provision for nothing.
     A Provision's entire value is the heal, so eating one at full HP destroys
     it and changes no visible state — which is precisely what beta testers
     read as "I clicked eat and nothing happened". Say so and keep the item.
     A Feast or Draught is spent for its timed buff, so full HP is never a
     reason to block it. opts.force exists for callers that mean it. */
  const atFull = typeof G.playerHp === 'number' && typeof G.playerMaxHp === 'number'
    && G.playerHp >= G.playerMaxHp;
  if(atFull && info && info.kind === 'provision' && !opts.force){
    if(typeof window.notify === 'function'){
      notify('Already at full health — kept your ' + (fd.n||foodId) + '.','info');
    }
    return false;
  }

  const hpBefore = (typeof G.playerHp === 'number') ? G.playerHp : null;

  // Heal if applicable
  if(fd.heals && typeof G.playerHp === 'number'){
    G.playerHp = Math.min(G.playerMaxHp || G.playerHp + fd.heals, G.playerHp + fd.heals);
  }

  // Apply buff
  if(fd.buff && typeof window.applyBuff === 'function'){
    window.applyBuff(fd.buff);
  }

  // Consume one
  G.inventory[foodId] = (G.inventory[foodId]||0) - 1;
  if(G.inventory[foodId] <= 0) delete G.inventory[foodId];

  G.stats = G.stats || {};
  G.stats.buffsConsumed = (G.stats.buffsConsumed||0) + 1;

  if(window.HearthriseEvents) window.HearthriseEvents.emit('eat', {foodId});

  /* b224: say what actually happened. The old toast was "Ate X — buff applied":
     no HP gained, no resulting HP, no buff named. */
  const gained = (hpBefore != null) ? (G.playerHp - hpBefore) : 0;
  if(typeof window.notify === 'function'){
    const parts = [];
    if(gained > 0) parts.push('+' + gained + ' HP (' + G.playerHp + '/' + G.playerMaxHp + ')');
    if(info && info.buffText) parts.push(info.buffText);
    const verbPast = (info && info.verbPast) || 'Ate';
    notify(verbPast + ' ' + (fd.n||foodId) + (parts.length ? ' — ' + parts.join(' · ') : ''),
           gained > 0 ? 'levelup' : 'loot');
  }
  /* Mid-fight the toast is not where the player is looking — mirror it into the
     combat log next to the auto-eat lines, and repaint the HP bar immediately. */
  if(G.activeMonster && Array.isArray(G.combatLog)){
    G.combatLog.push('Ate ' + (fd.n||foodId) + (gained > 0 ? ' (+' + gained + ' HP)' : ''));
    if(typeof window.renderCombat === 'function') window.renderCombat();
  }

  if(typeof window.renderInvFancy === 'function') window.renderInvFancy();
  if(typeof window.renderActiveEffects === 'function') window.renderActiveEffects();
  if(typeof window.updateTopbar === 'function') window.updateTopbar();
  return true;
};

// ── Tick: countdown active buffs only while an activity is running ──
let lastBuffTickAt = Date.now();
setInterval(function(){
  const now = Date.now();
  const elapsedMs = now - lastBuffTickAt;
  lastBuffTickAt = now;
  if(typeof G === 'undefined' || !Array.isArray(G.buffs) || G.buffs.length === 0) return;
  // Only tick during an active activity. Idle play doesn't drain buffs.
  const isActive = G.activeSkill || G.activeMonster || G.activeArtisanRecipe;
  if(!isActive) return;
  let changed = false;
  for(const b of G.buffs){
    b.remainingMs -= elapsedMs;
    if(b.remainingMs <= 0) changed = true;
  }
  if(changed) window.pruneBuffs();
  // Refresh UI without rebuilding everything — just text update on the timer
  refreshBuffTimers();
}, 1000);

// ── Hook into existing getBonus() so buffs apply ──
(function(){
  if(typeof window.getBonus !== 'function') return;
  const orig = window.getBonus;
  window.getBonus = function(key){
    let v = orig.apply(this, arguments) || 0;
    const buffs = window.getBuffBonuses();
    if(typeof buffs[key] === 'number') v += buffs[key];
    return v;
  };
})();

// b163: REMOVED the auto-eat watchdog that used to wrap combatTick here.
// It called eatFood(G.foodSlot) on low HP — which applies food BUFFS, not just
// heals — and then early-`return`ed, SKIPPING the entire real combat tick (no
// attack that tick) whenever foodSlot was set. Two bugs: (1) HP auto-eat should
// only HEAL, never spend buff items (buff consumption is a separate, opt-in,
// buff-expiry-driven concern — planned as a "drinks" category); (2) skipping the
// tick was never intended. HP auto-eat now flows solely through
// HearthriseAuto.maybeAutoEat() inside combatTick (heal-only), matching offline
// combat. Old G.foodSlot saves are migrated to G.autoActions.eat in
// auto-actions.js so nobody loses their auto-eat setting.

/* b224: REMOVED injectEatNowButtons() and its renderInvFancy wrapper.
   It looked for `#panel-inventory .invc-tile[data-item-id]` and skipped any
   tile without that attribute — but renderInvFancy() only sets data-item-id
   on EQUIPPABLE items (it drives drag-to-equip), and no food is equippable.
   The intersection was empty by construction, so this produced zero buttons
   on every render since the bag was rebuilt. Verified in-browser before
   deleting: `document.querySelectorAll('.eat-now-btn').length === 0` with a
   bag full of Provisions.

   It is not resurrected here: a floating button on a 44px tile fights the
   quantity badge and the rarity frame. Eat is now the primary action in the
   item flyout (one click from the tile) and a first-class button on the
   Combat screen, which is where healing is actually needed. */

// ── UI: refresh just the timer text without re-rendering the whole panel ──
function refreshBuffTimers(){
  const rows = document.querySelectorAll('.buff-row');
  rows.forEach(function(row){
    const t = row.querySelector('.br-time');
    if(!t) return;
    const idx = parseInt(row.getAttribute('data-buff-idx')||'-1', 10);
    if(isNaN(idx) || idx < 0 || !G || !G.buffs[idx]) return;
    t.textContent = formatRemaining(G.buffs[idx].remainingMs);
  });
}
function formatRemaining(ms){
  if(ms <= 0) return '0s';
  const s = Math.floor(ms/1000);
  if(s < 60) return s+'s';
  const m = Math.floor(s/60);
  const sr = s%60;
  return m+'m '+sr+'s';
}

// ── UI: render the Active Effects → FOOD BUFFS section ──
// Replace the existing renderActiveEffects food section with a queue view
window.__renderBuffsSection = function(){
  ensureBuffState();
  // renderActiveEffects() now emits a `<div id="food-buffs-host" data-managed-by="buff-queue">`
  // for us. If it's been rendered already, just populate it. Otherwise fall back to the
  // injection path so this still works on pages that don't render Active Effects.
  let host = document.getElementById('food-buffs-host');
  if(!host){
    const card = document.querySelector('.active-effects-card, #active-effects-card');
    if(card){
      host = document.createElement('div');
      host.id = 'food-buffs-host';
      host.style.marginTop = '8px';
      const heading = Array.from(card.querySelectorAll('*')).find(el => el.textContent.trim() === 'FOOD BUFFS');
      if(heading && heading.parentElement){
        heading.parentElement.insertBefore(host, heading.nextSibling);
      } else {
        card.appendChild(host);
      }
    }
  }
  if(!host) return;
  if(!G.buffs || G.buffs.length === 0){
    host.innerHTML = '<div style="color:var(--ink-3);font-size:calc(14.5px * var(--ui-scale, 1));font-style:italic">No food buffs active. Cook buff foods to add bonuses.</div>';
    return;
  }
  host.innerHTML = G.buffs.map(function(b, i){
    const def = BUFFS_DEF[b.type] || {label:b.type, isPercent:true, icon:'✨'};
    const display = def.isPercent ? '+'+b.magnitude+'%' : '+'+b.magnitude;
    return '<div class="buff-row" data-buff-idx="'+i+'">'
      +'<span class="br-icon">'+def.icon+'</span>'
      +'<span class="br-name">'+def.label+'</span>'
      +'<span class="br-mag">'+display+'</span>'
      +'<span class="br-time">'+formatRemaining(b.remainingMs)+'</span>'
    +'</div>';
  }).join('');
};

// Hook renderActiveEffects + renderProfile so our section refreshes
(function(){
  ['renderActiveEffects','renderProfile'].forEach(function(fnName){
    if(typeof window[fnName] !== 'function') return;
    const orig = window[fnName];
    window[fnName] = function(){
      const r = orig.apply(this, arguments);
      setTimeout(window.__renderBuffsSection, 30);
      return r;
    };
  });
})();

// ── Boot ──
function boot(){
  ensureBuffState();
  if(typeof window.renderActiveEffects === 'function') window.renderActiveEffects();
  /* b224: the injectEatNowButtons() boot call went with the function — see the
     note above. Eat now lives in the item flyout and the Combat screen. */
  setTimeout(window.__renderBuffsSection, 800);
}
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', function(){ setTimeout(boot, 400); });
} else {
  setTimeout(boot, 400);
}

console.log('[Buff Queue v1] loaded — '+Object.keys(BUFFS_DEF).length+' buff types registered');
})();

